"""Fetch pristine ExternalProject sources and reuse them across build trees.

The manifest and download-only CMake projects are generated by source_cache.cmake.
GitHub storage is handled by Actions; this helper also works without GitHub.
"""
import argparse
import hashlib
import json
import os
from pathlib import Path
import random
import re
import shutil
import stat
import subprocess
import tarfile
import tempfile
import time
import uuid


def archive_digest(archive):
    with archive.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def validate_snapshot(directory, entry):
    """Reject incomplete or mismatched entries rather than use wrong sources."""
    archive = directory / "source.tar.gz"
    metadata = json.loads(
        (directory / "source.json").read_text(encoding="utf-8"))
    if (metadata["key"] != entry["key"] or
            metadata["options"] != entry["options"] or
            metadata["sha256"] != archive_digest(archive)):
        raise ValueError(f"Invalid source snapshot: {directory}")
    return archive


def download_with_retry(command, *, attempts=4, retry_delay=15, timeout=900):
    """Retry only source acquisition, including failed submodule downloads.

Each invocation may include CMake's three immediate Git clone attempts. The
deadline bounds the combined invocations and exponential delays.
"""
    deadline = time.monotonic() + timeout
    permanent_error = re.compile(
        r"authentication failed|could not read username|"
        r"repository .*not found|couldn't find remote ref|"
        r"invalid reference|reference is not a tree|pathspec .*did not match",
        re.IGNORECASE)
    for attempt in range(attempts):
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise TimeoutError("Source download retry deadline exceeded")
        result = subprocess.run(command,
                                stdout=subprocess.PIPE,
                                stderr=subprocess.STDOUT,
                                text=True,
                                encoding="utf-8",
                                errors="replace",
                                timeout=remaining)
        print(result.stdout, end="", flush=True)
        if result.returncode == 0:
            return
        if attempt + 1 == attempts or permanent_error.search(result.stdout):
            raise subprocess.CalledProcessError(result.returncode,
                                                command,
                                                output=result.stdout)
        delay = min(retry_delay * 2**attempt, 60)
        # Add some randomness to the retry timer to avoid all runners
        # synchronizing their requests against an overloaded server
        delay += random.uniform(0, delay / 5)
        if delay >= deadline - time.monotonic():
            raise TimeoutError("Source download retry deadline exceeded")
        print(
            f"Source download failed; retrying in {delay:.1f}s "
            f"(attempt {attempt + 2}/{attempts})",
            flush=True)
        time.sleep(delay)


def remove_tree(directory):
    """Git object files can be read-only on Windows."""

    def make_writable(function, path, error):
        os.chmod(path, stat.S_IWRITE | stat.S_IREAD)
        function(path)

    shutil.rmtree(directory, onerror=make_writable)


def fetch(entry, cache_dir, *, cmake="cmake"):
    """Publish a complete archive atomically; never cache patches or stamps."""
    directory = Path(cache_dir).resolve() / entry["key"]
    if directory.exists():
        return validate_snapshot(directory, entry)
    directory.parent.mkdir(parents=True, exist_ok=True)
    work = Path(tempfile.mkdtemp(prefix="source-fetch-", dir=directory.parent))
    try:
        build = work / "build"
        subprocess.run([
            cmake, "-S", entry["fetch_project"], "-B",
            str(build), "-G", "Ninja"
        ],
                       check=True,
                       timeout=120)
        download_with_retry([
            cmake, "--build",
            str(build), "--target", "source-download", "--config", "Release"
        ])
        source = build / "source"
        if not source.is_dir() or not any(source.iterdir()):
            raise ValueError("Source download produced an empty directory")
        snapshot = work / "snapshot"
        snapshot.mkdir()
        archive = snapshot / "source.tar.gz"
        with tarfile.open(archive, "w:gz") as output:
            output.add(source, arcname="source")
        metadata = {
            "key": entry["key"],
            "options": entry["options"],
            "sha256": archive_digest(archive),
        }
        if (source / ".git").exists():
            metadata["revision"] = subprocess.check_output(
                ["git", "-C", str(source), "rev-parse", "HEAD"],
                text=True).strip()
        (snapshot / "source.json").write_text(json.dumps(metadata, indent=2) +
                                              "\n",
                                              encoding="utf-8")
        # Concurrent local builds may have completed the same source snapshot.
        try:
            snapshot.rename(directory)
        except OSError:
            if not directory.exists():
                raise
            validate_snapshot(directory, entry)
        return directory / "source.tar.gz"
    finally:
        remove_tree(work)


def materialize(entry, cache_dir, destination, *, cmake="cmake"):
    """Extract a private source tree; preserve Git and submodule metadata."""
    archive = fetch(entry, cache_dir, cmake=cmake)
    destination = Path(destination).resolve()
    destination.parent.mkdir(parents=True, exist_ok=True)
    work = Path(
        tempfile.mkdtemp(prefix="source-extract-", dir=destination.parent))
    try:
        with tarfile.open(archive) as source:
            source.extractall(work, filter="data")
        extracted = work / "source"
        if not extracted.is_dir() or not any(extracted.iterdir()):
            raise ValueError(f"Empty source snapshot: {archive}")
        if destination.exists():
            remove_tree(destination)
        extracted.rename(destination)
    finally:
        remove_tree(work)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "command", choices=["fetch", "materialize", "outputs", "entry-outputs"])
    parser.add_argument("--manifest", required=True, type=Path)
    parser.add_argument("--cache-dir", required=True, type=Path)
    parser.add_argument("--library")
    parser.add_argument("--key")
    parser.add_argument("--destination", type=Path)
    parser.add_argument("--cmake", default="cmake")
    args = parser.parse_args()
    manifest = json.loads(args.manifest.read_text(encoding="utf-8"))
    if args.command == "outputs":
        matrix = {
            "include": [{
                "library": name,
                "key": entry["key"],
                "cache-path": (args.cache_dir / entry["key"]).as_posix(),
            } for name, entry in manifest.items()]
        }
        print("source-matrix=" + json.dumps(matrix, separators=(",", ":")))
        print("source-artifact-prefix=external-sources-" + uuid.uuid4().hex)
        print("source-ref=" + subprocess.check_output(
            ["git", "rev-parse", "HEAD"], text=True).strip())
        return
    if args.library not in manifest:
        parser.error("--library must name a dependency in the manifest")
    entry = manifest[args.library]
    if args.key is not None and entry["key"] != args.key:
        parser.error(
            "source manifest changed; reconfigure the external project")
    if args.command == "entry-outputs":
        directory = args.cache_dir / entry["key"]
        print("key=" + entry["key"])
        print("path=" + directory.as_posix())
        available = (directory / "source.json").is_file() and (
            directory / "source.tar.gz").is_file()
        print("available=" + str(available).lower())
    elif args.command == "fetch":
        fetch(entry, args.cache_dir, cmake=args.cmake)
    else:
        if args.destination is None:
            parser.error("materialize requires --destination")
        materialize(entry, args.cache_dir, args.destination, cmake=args.cmake)


if __name__ == "__main__":
    main()
